"""Who holds which book, on disk so separate `shelf` processes agree.

The title is the primary key, so the database itself guarantees at most one
holder per book: when two lends race, exactly one INSERT wins.
"""
import os
import sqlite3


class AlreadyLent(Exception):
    pass


class NotLent(Exception):
    pass


def _db_path():
    return os.environ.get("SHELF_DB", "shelf.db")


def _connect():
    conn = sqlite3.connect(_db_path(), timeout=30)
    conn.execute(
        "CREATE TABLE IF NOT EXISTS loans (title TEXT PRIMARY KEY, member TEXT NOT NULL)"
    )
    return conn


def lend(title, member):
    conn = _connect()
    try:
        with conn:
            conn.execute("INSERT INTO loans (title, member) VALUES (?, ?)", (title, member))
    except sqlite3.IntegrityError:
        raise AlreadyLent("%s is already lent to %s" % (title, holder(title)))
    finally:
        conn.close()


def return_book(title):
    conn = _connect()
    try:
        with conn:
            cur = conn.execute("DELETE FROM loans WHERE title = ?", (title,))
    finally:
        conn.close()
    if cur.rowcount == 0:
        raise NotLent("%s is not lent out" % title)


def holder(title):
    conn = _connect()
    try:
        row = conn.execute("SELECT member FROM loans WHERE title = ?", (title,)).fetchone()
    finally:
        conn.close()
    return row[0] if row else None

